style.css:
@-moz-document domain("icourse163.org") {
/* 设置页面主体背景为黑色 */
    body {
        background-color: black!important;
    }
    /* 将页面文字颜色统一设为白色，方便查看内容，可按需更改颜色 */
    body,
    p,
    h1,
    h2,
    h3,
    h4,
    h5,
    h6,
    div,
    span,
    li,
    a,
    label,
    button,
    input,
    textarea {
        color: white!important;
    }
    /* 调整导航栏等头部区域背景和文字颜色等样式 */
   .ntes-nav-header {
        background-color: #222!important;
    }
   .ntes-nav-header a {
        color: #ccc!important;
    }
    /* 课程卡片区域相关样式调整 */
   .u-course-card {
        background-color: #111!important;
    }
   .u-course-card.course-card-content.course-title {
        color: #fff!important;
    }
   .u-course-card.course-card-content.course-teacher {
        color: #aaa!important;
    }
    /* 按钮样式调整 */
    button {
        background-color: #333!important;
        border: 1px solid #555!important;
        color: white!important;
    }
    /* 输入框样式调整 */
    input[type="text"],
    input[type="password"],
    textarea {
        background-color: #333!important;
        color: white!important;
    }
    /* 页脚区域样式调整 */
   .footer {
        background-color: #222!important;
    }
   .footer a {
        color: #ccc!important;
    }
}
